// RequestOtp is the resolver for the requestOTP field.
func (r *mutationResolver) RequestOtp(ctx context.Context, email string, clientID string) (*auth.AuthResponse, error) {
	otp, err := r.OTPSvc.Generate(email, clientID)
	if err != nil {
		return &auth.AuthResponse{Success: false, Error: err.Error()}, nil
	}
	if err := r.EmailSvc.SendOTP(email, otp); err != nil {
		return &auth.AuthResponse{Success: false, Error: "failed to send email"}, nil
	}
	return &auth.AuthResponse{Success: true}, nil
}

// VerifyOtp is the resolver for the verifyOTP field.
func (r *mutationResolver) VerifyOtp(ctx context.Context, email string, otp string, clientID string) (*auth.AuthResponse, error) {
	if err := r.OTPSvc.Verify(email, otp); err != nil {
		return &auth.AuthResponse{Success: false, Error: err.Error()}, nil
	}
	provider := "email_passwordless"
	address := r.WalletSvc.DeriveAddress(email)
	apiKey := createUserAPIKey(email, address)

	// 仅从合约读取用户，避免本地读取
	if existing, _ := getAuthUserFromContract(r.TeeChain, email); existing == nil {
		model.PutAuthUser(&model.AuthUser{
			Email:   email,
			Address: address,
		})
	} else {
		// 更新地址（可能因恢复等原因变化）
		existing.Address = address
		model.PutAuthUser(existing)
	}

	return &auth.AuthResponse{
		Success:  true,
		Token:    apiKey,
		Address:  address,
		UserInfo: &auth.UserInfo{Email: email, Name: email, TypeOfLogin: provider},
	}, nil
}

// SocialLogin is the resolver for the socialLogin field.
func (r *mutationResolver) SocialLogin(ctx context.Context, provider string, idToken *string, code *string, codeVerifier *string) (*auth.AuthResponse, error) {
	var oauthUser *auth.OAuthUserInfo
	var err error

	switch provider {
	case "google":
		if idToken != nil && *idToken != "" {
			oauthUser, err = r.OAuthSvc.VerifyGoogleIDToken(*idToken)
		} else if code != nil && *code != "" {
			oauthUser, err = r.OAuthSvc.ExchangeGoogleCode(*code)
		}
	case "github":
		if code != nil && *code != "" {
			oauthUser, err = r.OAuthSvc.ExchangeGitHubCode(*code)
		}
	case "twitter", "x":
		v := ""
		if codeVerifier != nil {
			v = *codeVerifier
		}
		c := ""
		if code != nil {
			c = *code
		}
		oauthUser, err = r.OAuthSvc.ExchangeXCode(c, v)
	default:
		return &auth.AuthResponse{Success: false, Error: "unsupported provider: " + provider}, nil
	}

	if err != nil {
		return &auth.AuthResponse{Success: false, Error: err.Error()}, nil
	}

	address := r.WalletSvc.DeriveAddress(oauthUser.Email)
	apiKey := createUserAPIKey(oauthUser.Email, address)
	userInfo := &auth.UserInfo{
		Email:        oauthUser.Email,
		Name:         oauthUser.Name,
		ProfileImage: oauthUser.AvatarURL,
		TypeOfLogin:  provider,
		Verifier:     provider,
		VerifierID:   oauthUser.ProviderID,
	}

	// 仅从合约读取用户，避免本地读取
	if existing, _ := getAuthUserFromContract(r.TeeChain, oauthUser.Email); existing == nil {
		model.PutAuthUser(&model.AuthUser{
			Email: oauthUser.Email, Address: address,
		})
	} else {
		existing.Address = address
		model.PutAuthUser(existing)
	}

	return &auth.AuthResponse{
		Success: true, UserInfo: userInfo, Token: apiKey, Address: address,
	}, nil
}

// SetPassword is the resolver for the setPassword field.
// 同时保存 passwordHash（用于解密私钥）和 salt + dkHash（用于 challenge-response 验证）
func (r *mutationResolver) SetPassword(ctx context.Context, token string, passwordHash string, salt string, dkHash string) (*auth.WalletResult, error) {
	email, err := resolveEmailFromToken(token)
	if err != nil {
		return &auth.WalletResult{Status: "error", Error: "unauthorized"}, nil
	}
	// 加密私钥
	if err := r.WalletSvc.EncryptPrivateKey(email, passwordHash); err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}
	// 存储密码信息到用户记录
	user, _ := getAuthUserFromContract(r.TeeChain, email)
	if user == nil {
		user = &model.AuthUser{Email: email}
	}
	user.PasswordHash = passwordHash
	user.Salt = salt
	user.DKHash = dkHash
	if err := model.PutAuthUser(user); err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}

	// 异步上链：同步 AuthUser 到合约，支持跨节点登录
	go func(u *model.AuthUser) {
		plain, _ := json.Marshal(u)
		_ = r.TeeChain.AuthStoreAuthUser("auth_user:"+u.Email, plain)
	}(user)

	return &auth.WalletResult{Status: "ok"}, nil
}

// VerifyPassword is the resolver for the verifyPassword field.
func (r *mutationResolver) VerifyPassword(ctx context.Context, token string, passwordHash string) (*model.SignSessionResult, error) {
	email, err := resolveEmailFromToken(token)
	if err != nil {
		e := "unauthorized"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 从合约读取用户并验证密码 hash
	user, err := getAuthUserFromContract(r.TeeChain, email)
	if err != nil || user == nil {
		e := "user not found"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 如果用户没有设置过密码，先尝试用传入的密码初始化
	if user.PasswordHash == "" {
		// 首次设置密码：加密私钥并存储
		if err := r.WalletSvc.EncryptPrivateKey(email, passwordHash); err != nil {
			e := err.Error()
			return &model.SignSessionResult{Status: "error", Error: &e}, nil
		}
		user.PasswordHash = passwordHash
		model.PutAuthUser(user)
	} else if user.PasswordHash != passwordHash {
		e := "wrong password"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 生成短期签名 token（5 分钟有效）
	signToken := fmt.Sprintf("sig_%d_%s", time.Now().Unix(), email)
	expiresAt := time.Now().Add(5 * time.Minute).Unix()
	if err := model.PutSignSession(&model.SignSession{
		Token:     signToken,
		Email:     email,
		ExpiresAt: expiresAt,
	}); err != nil {
		e := "failed to create session"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	et := int(expiresAt)
	return &model.SignSessionResult{
		Status:    "ok",
		SignToken: &signToken,
		ExpiresAt: &et,
	}, nil
}

// VerifyResponse is the resolver for the verifyResponse field.
// challenge-response 验证：前端用 PBKDF2(password, salt) 派生 dk，然后 HMAC-SHA256(dk, challenge)
// 参数 challenge 用于精确定位要验证的 challenge，避免多 challenge 错位
func (r *mutationResolver) VerifyResponse(ctx context.Context, token string, challenge string, response string) (*model.SignSessionResult, error) {
	email, err := resolveEmailFromToken(token)
	if err != nil {
		e := "unauthorized"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 检查是否被锁定
	if model.IsLocked(email) {
		e := "Too many failed attempts"
		return &model.SignSessionResult{Status: "locked", Error: &e}, nil
	}

	// 从合约读取用户信息
	user, err := getAuthUserFromContract(r.TeeChain, email)
	if err != nil || user == nil {
		e := "user not found"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	if user.DKHash == "" {
		e := "password not set"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 获取指定的 challenge 记录
	rec, err := model.GetChallenge(email, challenge)
	if err != nil || rec == nil {
		e := "invalid challenge"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	if rec.Used {
		e := "challenge already used"
		return &model.SignSessionResult{Status: "error", Error: &e}, nil
	}

	// 验证 HMAC
	expected := computeHMAC(user.DKHash, challenge)
	isValid := hmac.Equal([]byte(expected), []byte(response))

	// 标记该 challenge 已使用（无论成败）
	model.MarkChallengeUsed(email, challenge)

	if isValid {
		// 重置失败计数
		model.ResetFailedChallenge(email)

		// 生成短期签名 token（60 秒有效）
		signToken := fmt.Sprintf("sig_%d_%s", time.Now().Unix(), email)
		expiresAt := time.Now().Add(60 * time.Second).Unix()
		if err := model.PutSignSession(&model.SignSession{
			Token:        signToken,
			Email:        email,
			ExpiresAt:    expiresAt,
			PasswordHash: user.PasswordHash, // 关联 passwordHash，签名时复用
		}); err != nil {
			e := "failed to create session"
			return &model.SignSessionResult{Status: "error", Error: &e}, nil
		}

		et := int(expiresAt)
		return &model.SignSessionResult{
			Status:    "ok",
			SignToken: &signToken,
			ExpiresAt: &et,
		}, nil
	}

	// 失败计数
	fails, _ := model.IncrFailedChallenge(email)
	if fails >= 5 {
		// 锁定 30 分钟：实际由 IsLocked 检查失败次数 >= 5
	}

	e := "wrong password"
	return &model.SignSessionResult{Status: "error", Error: &e}, nil
}

// SignTransaction is the resolver for the signTransaction field.
// token 可以是登录 JWT 或短期签名 token
func (r *mutationResolver) SignTransaction(ctx context.Context, token string, tx auth.TxInput) (*auth.WalletResult, error) {
	email, err := r.Resolver.ResolveSignerEmail(token)
	if err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}

	// 获取 passwordHash：如果是 signToken，从 session 中获取（一次性）
	var passwordHash string
	if len(token) > 4 && token[:4] == "sig_" {
		session, err := model.GetSignSession(token)
		if err != nil || session == nil {
			return &auth.WalletResult{Status: "error", Error: "invalid sign token"}, nil
		}
		passwordHash = session.PasswordHash
		// 使用后删除 signToken（一次性）
		model.DeleteSignSession(token)
	} else {
		// API Key 模式下需要传入 passwordHash
		passwordHash = tx.PasswordHash
	}

	raw, err := r.WalletSvc.SignTx(email, &wallet.TxRequest{
		From:         tx.From,
		To:           tx.To,
		Value:        tx.Value,
		Data:         tx.Data,
		Gas:          tx.Gas,
		GasPrice:     tx.GasPrice,
		Nonce:        tx.Nonce,
		ChainID:      tx.ChainID,
		PasswordHash: passwordHash,
	})
	if err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}
	return &auth.WalletResult{Status: "ok", Result: raw}, nil
}

// SignMessage is the resolver for the signMessage field.
// token 可以是登录 JWT 或短期签名 token
func (r *mutationResolver) SignMessage(ctx context.Context, token string, message string, from string, passwordHash *string) (*auth.WalletResult, error) {
	email, err := r.Resolver.ResolveSignerEmail(token)
	if err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}

	var pwd string
	if len(token) > 4 && token[:4] == "sig_" {
		// signToken 模式：从 session 获取 passwordHash（一次性）
		session, err := model.GetSignSession(token)
		if err != nil || session == nil {
			return &auth.WalletResult{Status: "error", Error: "invalid sign token"}, nil
		}
		pwd = session.PasswordHash
		// 使用后删除 signToken
		model.DeleteSignSession(token)
	} else if passwordHash != nil {
		pwd = *passwordHash
	}

	sig, err := r.WalletSvc.SignMessage(email, message, pwd)
	if err != nil {
		return &auth.WalletResult{Status: "error", Error: err.Error()}, nil
	}
	return &auth.WalletResult{Status: "ok", Result: sig}, nil
}

// RequestRecovery is the resolver for the requestRecovery field.
func (r *mutationResolver) RequestRecovery(ctx context.Context, recoveryEmail string) (*auth.RecoveryResult, error) {
	rec, err := model.FindRecoveryByEmail(recoveryEmail)
	if err != nil || rec == nil {
		return &auth.RecoveryResult{Status: "error", Error: "no recovery config for this email"}, nil
	}

	otp := fmt.Sprintf("%06d", time.Now().UnixNano()%1000000)
	model.PutRecoveryOTP(rec.UserEmail, otp)
	return &auth.RecoveryResult{Status: "ok"}, nil
}

// VerifyRecovery is the resolver for the verifyRecovery field.
func (r *mutationResolver) VerifyRecovery(ctx context.Context, recoveryEmail string, otp string) (*auth.RecoveryResult, error) {
	rec, err := model.FindRecoveryByEmail(recoveryEmail)
	if err != nil || rec == nil {
		return &auth.RecoveryResult{Status: "error", Error: "not found"}, nil
	}

	stored, _ := model.GetRecoveryOTP(rec.UserEmail)
	if stored != otp {
		return &auth.RecoveryResult{Status: "error", Error: "invalid OTP"}, nil
	}
	model.DeleteRecoveryOTP(rec.UserEmail)

	// 生成恢复用的短期签名 token（10 分钟有效）
	recoveryToken := fmt.Sprintf("sig_%d_%s", time.Now().Unix(), rec.UserEmail)
	expiresAt := time.Now().Add(10 * time.Minute).Unix()
	if err := model.PutSignSession(&model.SignSession{
		Token:        recoveryToken,
		Email:        rec.UserEmail,
		ExpiresAt:    expiresAt,
		PasswordHash: "", // 恢复流程不关联 passwordHash
	}); err != nil {
		return &auth.RecoveryResult{Status: "error", Error: "token issue failed"}, nil
	}
	return &auth.RecoveryResult{Status: "ok", RecoveryToken: recoveryToken}, nil
}

// CompleteRecovery is the resolver for the completeRecovery field.
func (r *mutationResolver) CompleteRecovery(ctx context.Context, recoveryToken string, passwordHash string) (*auth.RecoveryResult, error) {
	email, err := resolveEmailFromToken(recoveryToken)
	if err != nil {
		return &auth.RecoveryResult{Status: "error", Error: "invalid token"}, nil
	}

	if err := r.WalletSvc.EncryptPrivateKey(email, passwordHash); err != nil {
		return &auth.RecoveryResult{Status: "error", Error: err.Error()}, nil
	}

	address := r.WalletSvc.DeriveAddress(email)
	apiKey := createUserAPIKey(email, address)
	return &auth.RecoveryResult{
		Status: "ok", Token: apiKey, Address: address, Email: email,
	}, nil
}

